// Fills afValues with a symmetric 100-point curve, maps it from afStart to afEnd, and stores start, end and duration unless the GetTime64 check fails.
// @fnv 0x00946020
bool FadeCurve::FUN_00946020(float afStart, float afEnd, float afDuration)
{
    float fValue = 0.0f;
    float fStep2 = 0.02f;
    float fStepIncrease = 0.04f;
    for (int i = 0; i < 50; i++)
    {
        afValues[i] = fValue / 99.0f;
        afValues[99 - i] = (99.0f - fValue) / 99.0f;
        fValue += fStep2;
        fStep2 += fStepIncrease;
    }
    for (int j = 0; j < 100; j++)
        afValues[j] = LinearInterpolate(afStart, afEnd, 0.0f, 1.0f, afValues[j]);

    if (!(reinterpret_cast<std::intptr_t>(GetTime64) > 0))
        return false;
    fStart = afStart;
    m_fEndValue = afEnd;
    fDuration = afDuration;
    fDuration2 = afDuration;
    return true;
}

