// Adds a perk to the entry or companion list for its entry-list index when the perk is type 2 and the index is below 0x4A.
// @fnv 0x00963b20
void PerkCharacter::RegisterPerk(PerkData* perk, bool companion)
{
    if (perk == 0 || perk->GetType() != 2)
    {
        return;
    }
    PerkData* entry = perk;
    unsigned char ep = reinterpret_cast<::FUN_0062f2f0_shell *>((entry))->FUN_0062f2f0();
    if (ep >= 0x4A)
    {
        return;
    }
    if (!companion)
    {
        reinterpret_cast<::ItemChangeListNode *>(&(entryLists[ep]))->FUN_00905330((*(::InventoryStackRecord *const *)(&perk)));
    }
    else
    {
        reinterpret_cast<::ItemChangeListNode *>(&(companionLists[ep]))->FUN_00905330((*(::InventoryStackRecord *const *)(&perk)));
    }
}

struct FUN_00963ba0_t
{
    void* GetSlotPointer(unsigned char a, unsigned char b);
};
// Returns null if a >= 0x4a, otherwise a pointer at offset a*8 plus 0x884 when b is zero or 0xadc when b is non-zero.
// @fnv 0x00963ba0
void* FUN_00963ba0_t::GetSlotPointer(unsigned char aiIndex, unsigned char abFlag)
{
    if (aiIndex >= 0x4a)
        return 0;
    if (!abFlag)
        return (char*)this + aiIndex * 8 + 0x884;
    else
        return (char*)this + aiIndex * 8 + 0xadc;
}

